<?php
declare(strict_types=1); require __DIR__.'/includes/auth_guard.php';
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1){flash('danger','Invalid building ID.');redirect('adminpage.php');}$row=$buildingModel->find($id);if(!$row){flash('danger','Building not found.');redirect('adminpage.php');}$errors=[];$name=$row['bname'];$description=$row['description'];
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim((string)($_POST['bname']??''));$description=trim((string)($_POST['description']??''));if(!verify_csrf($_POST['csrf_token']??null))$errors[]='Invalid form token. Please try again.';if($name==='')$errors[]='Building name is required.';if(!$errors){$newImage=null;try{$newImage=image_upload();$buildingModel->update($id,$name,$description,$newImage);if($newImage)delete_uploaded_image((string)$row['img']);flash('success','Building updated successfully.');redirect('adminpage.php');}catch(Throwable $e){error_log($e->getMessage());if($newImage)delete_uploaded_image($newImage);$errors[]='The building could not be updated.';}}}
$pageTitle='Edit Building';require __DIR__.'/includes/admin_header.php';
?><div class="admin-card form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><div class="mb-3"><label class="form-label">Building name</label><input class="form-control" name="bname" value="<?=e($name)?>" required></div><div class="mb-3"><label class="form-label">Current image</label><br><?php if($row['img']):?><img class="current-image" src="<?=e($row['img'])?>" alt="Current building image"><?php endif;?></div><div class="mb-3"><label class="form-label">Replace image (optional)</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="8"><?=e($description)?></textarea></div><button class="btn btn-success">Update</button> <a class="btn btn-secondary" href="adminpage.php">Cancel</a></form></div><?php require __DIR__.'/includes/admin_footer.php';?>
